on conflict (code) do update set name=excluded.name,input_formats=excluded.input_formats,parser_contract=excluded.parser_contract,canonical_output_contract=excluded.canonical_output_contract,validation_contract=excluded.validation_contract,status=excluded.status,updated_at=now();